#!/usr/bin/env python3
"""ActuarIA — Installeur INFRA"""
import os, base64
print("ActuarIA — Installation INFRA")
print("=" * 50)

with open("managers_directeurs.py", "wb") as fh:
    fh.write(base64.b64decode(""))
print("Cree : managers_directeurs.py (681 lignes)")

with open("actuaria_app.py", "wb") as fh:
    fh.write(base64.b64decode(""))
print("Cree : actuaria_app.py (1221 lignes)")

with open("test_pipeline_non_vie.py", "wb") as fh:
    fh.write(base64.b64decode(""))
print("Cree : test_pipeline_non_vie.py (272 lignes)")

with open("deploy_actuaria.py", "wb") as fh:
    fh.write(base64.b64decode(""))
print("Cree : deploy_actuaria.py (819 lignes)")

print()
print("INSTALLATION TERMINEE")
ok = True
if os.path.exists("managers_directeurs.py"): print("  OK : managers_directeurs.py")
else: print("  KO : managers_directeurs.py"); ok = False
if os.path.exists("actuaria_app.py"): print("  OK : actuaria_app.py")
else: print("  KO : actuaria_app.py"); ok = False
if os.path.exists("test_pipeline_non_vie.py"): print("  OK : test_pipeline_non_vie.py")
else: print("  KO : test_pipeline_non_vie.py"); ok = False
